// Placeholder looks built from engine assets only, so the game needs no art to run (GDD 0.1 "Placeholders first").
#pragma once

#include "CoreMinimal.h"

class UStaticMesh;
class UStaticMeshComponent;
class UMaterialInstanceDynamic;

enum class EGBShape : uint8
{
	Cube,
	Sphere,
	Cylinder,
	Cone,
	Plane
};

/**
 * Engine basic shapes (/Engine/BasicShapes/*, 100 cm across) tinted with a dynamic material.
 * Use it for everything 3D that has no art yet: guns, cyberpunk props, walls, floors, 3D enemies.
 * Pixel-art things use UGBPixelSpriteLibrary instead (art rule, GDD 3).
 * Assets are loaded at runtime with LoadObject; DefaultGame.ini keeps them in the cook.
 */
namespace GBPlaceholder
{
	GLYPHBOUND_API UStaticMesh* GetShapeMesh(EGBShape Shape);

	/**
	 * Gives a mesh component a shape, scales it to SizeCm (full extent on each axis, in the component's local
	 * space) and tints it. bGlow uses the engine's unlit additive material (spell and neon looks) instead of
	 * the lit one. Returns the dynamic material so the caller can change the color later ("Color" parameter).
	 * Does not touch the component's collision settings.
	 */
	GLYPHBOUND_API UMaterialInstanceDynamic* SetupShape(UStaticMeshComponent* Component, EGBShape Shape, const FVector& SizeCm, const FLinearColor& Color, bool bGlow = false);

	/** Changes the tint of a component set up with SetupShape. */
	GLYPHBOUND_API void SetShapeColor(UStaticMeshComponent* Component, const FLinearColor& Color);

	/** Display color of an element, for placeholders and HUD (fire = orange, lightning = yellow, ice = cyan...). */
	GLYPHBOUND_API FLinearColor ElementColor(uint8 ElementAsByte);
}

// Shared enums and small structs used by every Glyphbound system.
#pragma once

#include "CoreMinimal.h"
#include "GBTypes.generated.h"

GLYPHBOUND_API DECLARE_LOG_CATEGORY_EXTERN(LogGB, Log, All);

/** The two times of the map (GDD 4). */
UENUM(BlueprintType)
enum class EGBEra : uint8
{
	Past,
	Future
};

/** In which era(s) an actor exists. */
UENUM(BlueprintType)
enum class EGBEraPresence : uint8
{
	Both,
	PastOnly,
	FutureOnly
};

UENUM(BlueprintType)
enum class EGBElement : uint8
{
	Physical,
	Arcane,
	Fire,
	Lightning,
	Ice,
	Air
};

/** Held slots (GDD 8): one staff, one gun, and later the elemental sword. */
UENUM(BlueprintType)
enum class EGBHeldSlot : uint8
{
	Staff,
	Gun,
	Sword
};

UENUM(BlueprintType)
enum class EGBTeam : uint8
{
	Neutral,
	Player,
	Enemy
};

/** Which QTE part scales a spell parameter (GDD 7): part 1 = power, part 2 = reach. */
UENUM(BlueprintType)
enum class EGBScaleSource : uint8
{
	None,
	Power,
	Reach
};

UENUM(BlueprintType)
enum class EGBModOp : uint8
{
	Add,
	Multiply,
	Override
};

/** HUD skin, chosen by the held item (GDD 13). */
UENUM(BlueprintType)
enum class EGBHudSkin : uint8
{
	Rpg90s,
	Cyberpunk
};

UENUM(BlueprintType)
enum class EGBItemType : uint8
{
	Consumable,
	Throwable,
	Armor,
	KeyItem,
	Material,
	Ammo
};

/** One hit. Everything that hurts something goes through UGBCombatLibrary::DealDamage with one of these. */
USTRUCT(BlueprintType)
struct GLYPHBOUND_API FGBDamageInfo
{
	GENERATED_BODY()

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	float Amount = 0.f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	EGBElement Element = EGBElement::Physical;

	/** Who is responsible (the player pawn, an enemy). Used for teams and kill credit. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	TObjectPtr<AActor> Instigator = nullptr;

	/** The thing that touched the target (projectile, wall, trap). May be null. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	TObjectPtr<AActor> Causer = nullptr;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	FVector HitLocation = FVector::ZeroVector;

	/** Direction the damage travels (from the source towards the target), normalized or zero. */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	FVector HitDirection = FVector::ZeroVector;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	bool bHeadshot = false;

	/** Spell, weapon or effect id that produced the hit (for logs, HUD and synergies). */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	FName SourceId = NAME_None;

	/** Optional status effect applied to the target on hit (id from StatusEffects.json). */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	FName OnHitEffect = NAME_None;

	/** Scales the duration / strength of OnHitEffect (1 = as defined in data). */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	float EffectDurationScale = 1.f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Damage")
	float EffectStrengthScale = 1.f;
};

