IMPLEMENT_SIMPLE_AUTOMATION_TEST(FGBProgressionUnlockRulesTest, "Glyphbound.Progression.UnlockRules",
	EAutomationTestFlags::EditorContext | EAutomationTestFlags::EngineFilter)

bool FGBProgressionUnlockRulesTest::RunTest(const FString& Parameters)
{
	const FName NodeId(TEXT("Node"));
	const FName ReqId(TEXT("Req"));
	using R = EGBSkillUnlockResult;

	// Not enough points: one short fails, exactly the cost passes.
	{
		const FGBSkillNodeDefinition Node = MakeNode(NodeId, 2, 3);
		const TMap<FName, int32> Ranks;
		TestEqual(TEXT("1 point for a cost of 2"), UGBSkillTreeComponent::EvaluateUnlock(Node, Ranks, 1), R::NotEnoughPoints);
		TestEqual(TEXT("exactly the cost"), UGBSkillTreeComponent::EvaluateUnlock(Node, Ranks, 2), R::Ok);
	}

	// Missing requirement, even with plenty of points and even when the requirement is listed at rank 0.
	{
		const FGBSkillNodeDefinition Node = MakeNode(NodeId, 1, 3, { ReqId });
		TestEqual(TEXT("requirement absent"), UGBSkillTreeComponent::EvaluateUnlock(Node, {}, 10), R::MissingRequirement);
		TestEqual(TEXT("requirement at rank 0"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { ReqId, 0 } }, 10), R::MissingRequirement);
		TestEqual(TEXT("missing requirement is reported before lack of points"), UGBSkillTreeComponent::EvaluateUnlock(Node, {}, 0), R::MissingRequirement);
		TestEqual(TEXT("requirement owned"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { ReqId, 1 } }, 10), R::Ok);
	}

	// Max rank: checked first, and one rank below it is still unlockable.
	{
		const FGBSkillNodeDefinition Node = MakeNode(NodeId, 1, 3, { ReqId });
		TestEqual(TEXT("at max rank"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { NodeId, 3 }, { ReqId, 1 } }, 10), R::MaxRank);
		TestEqual(TEXT("max rank is reported before missing requirement and points"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { NodeId, 3 } }, 0), R::MaxRank);
		TestEqual(TEXT("one rank below max"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { NodeId, 2 }, { ReqId, 1 } }, 1), R::Ok);
	}

	// Ok: another node's rank does not count as this node's rank.
	{
		const FGBSkillNodeDefinition Node = MakeNode(NodeId, 1, 1);
		TestEqual(TEXT("fresh node"), UGBSkillTreeComponent::EvaluateUnlock(Node, { { ReqId, 5 } }, 1), R::Ok);
	}

	return true;
}

#endif

