 */
template <typename TSubsystemClass>
TSubsystemClass* GetSubsystem() const
{
	return SubsystemCollection.GetSubsystem<TSubsystemClass>(TSubsystemClass::StaticClass());
}

/**
 * Get a Subsystem of specified type from the provided LocalPlayer
 * returns nullptr if the Subsystem cannot be found or the LocalPlayer is null
 */
template <typename TSubsystemClass>
static inline TSubsystemClass* GetSubsystem(const ULocalPlayer* LocalPlayer)
{
	if (LocalPlayer)
	{
		return LocalPlayer->GetSubsystem<TSubsystemClass>();
	}
	return nullptr;
}

/**
 * Get a subsystem of the specificied type from the provided Player Controller's owning ULocalPlayer.
 * Returns nullptr if the Subsystem cannot be found or the given controller or its local player are null.
 */
template <typename TSubsystemClass>
static FORCEINLINE TSubsystemClass* GetSubsystemFromController(const APlayerController* PC)
{
	if (PC)
	{
		const ULocalPlayer* LocalPlayer = PC->GetLocalPlayer();
		return LocalPlayer ? LocalPlayer->GetSubsystem<TSubsystemClass>() : nullptr;
	}
	return nullptr;
}

