{
	Super::BeginPlay();

	SetPlaceholderLook(false, NAME_None, BodyColor, BodySize);
	GBPlaceholder::SetupShape(Lid, EGBShape::Cube, LidSize, LidColor, false);

	const UGBProgressSubsystem* Progress = UGBProgressSubsystem::Get(this);
	SetOpenLook(Progress && Progress->HasFlag(GetOpenedFlag()));
}

